def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opp_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        bid = max(DAILY_SALARY * 0.95, highest_prev_bid + 2.5)
    elif my_urgent:
        bid = max(DAILY_SALARY * 0.82, highest_prev_bid + 1.5)
    else:
        if supply >= 23:
            bid = max(DAILY_SALARY * 0.32, avg_prev_bid * 0.55)
        elif supply >= 20:
            bid = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.72)
        elif supply >= 17:
            bid = max(DAILY_SALARY * 0.58, highest_prev_bid * 0.82)
        else:
            bid = max(DAILY_SALARY * 0.72, highest_prev_bid + 1.0)

    if rich_opp_count >= 2 and supply <= 18 and not my_urgent:
        bid = max(bid, highest_prev_bid + 1.0)

    if urgent_opp_count >= 2 and hp >= 5 and no_water_days == 0 and supply >= 20:
        bid = min(bid, DAILY_SALARY * 0.42)

    if day >= 8 and hp >= 5 and no_water_days == 0:
        bid = min(bid, max(DAILY_SALARY * 0.38, avg_prev_bid * 0.7 if prev_bids else DAILY_SALARY * 0.38))

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = avg_bid * 1.05
    else:
        target_bid = DAILY_SALARY * 0.6

    if my_status['hp'] < 5:
        target_bid = max(target_bid, DAILY_SALARY * 0.85)

    return min(my_status['budget'], target_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    num_winners = supply // WATER_REQ
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opp = [o for o in opponents_status.values() if o['alive']]
    max_prev_bid = 0.0
    for opp in alive_opp:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            max_prev_bid = max(max_prev_bid, trace['bid'])

    # Base bid: try to secure a win with minimal waste
    if num_winners == 1:
        # Need to be top, be aggressive based on threat
        if hp <= 2 or no_water > 0:
            bid = min(budget, DAILY_SALARY * 0.95)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.7, max_prev_bid + 1.0))
    elif num_winners == 2:
        # Need top 2
        if hp <= 2 or no_water > 0:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.5, max_prev_bid + 0.5))
    else:  # 3 winners
        if hp <= 2 or no_water > 0:
            bid = min(budget, DAILY_SALARY * 0.8)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.35, max_prev_bid + 0.2))

    # Ensure minimum bid if absolutely necessary
    if hp <= 1 and no_water >= 1:
        bid = min(budget, DAILY_SALARY * 0.95)

    # Always respect budget
    return max(1.0, min(bid, budget))
